class Solution {
  private static void mark(char[] text, char[] pat, int[] diff) {
    int m = pat.length;
    int[] fail = new int[m];
    for (int i = 1, k = 0; i < m; i++) {
      while (k > 0 && pat[i] != pat[k]) k = fail[k - 1];
      if (pat[i] == pat[k]) k++;
      fail[i] = k;
    }
    for (int i = 0, k = 0; i < text.length; i++) {
      while (k > 0 && (k == m || text[i] != pat[k])) k = fail[k - 1];
      if (text[i] == pat[k]) k++;
      if (k == m) {
        diff[i - m + 1]++;
        diff[i + 1]--;
      }
    }
  }

  public int countCells(char[][] grid, String pattern) {
    int m = grid.length, n = grid[0].length, total = m * n;
    char[] pat = pattern.toCharArray();
    if (pat.length > total) return 0;
    char[] h = new char[total], v = new char[total];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        h[i * n + j] = grid[i][j];
        v[j * m + i] = grid[i][j];
      }
    }
    int[] dh = new int[total + 1], dv = new int[total + 1];
    mark(h, pat, dh);
    mark(v, pat, dv);
    boolean[] coveredH = new boolean[total], coveredV = new boolean[total];
    int run = 0;
    for (int i = 0; i < total; i++) {
      run += dh[i];
      coveredH[i] = run > 0;
    }
    run = 0;
    for (int i = 0; i < total; i++) {
      run += dv[i];
      coveredV[i] = run > 0;
    }
    int ans = 0;
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) if (coveredH[i * n + j] && coveredV[j * m + i]) ans++;
    return ans;
  }
}
